; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: cpcfw (Amstrad CPC - firmware text and keys), starts in normal mode
; ============================================================

			DEVICE AMSTRADCPC6128		; for SAVEAMSDOS at the end
			org #0040

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 255		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs

ntc_start:
			di
			call ntc_rj_find		; Library: ROM - find the ROM, patch the jump block
			jr nc, ntc_rj_ok
			ei
			ret				; no ROM (the message is shown): back to the caller
ntc_rj_ok:
			ld hl, ntc_rj_exit
			push hl			; End comes back here: the caller's ROM selection again
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them

			; 12: Cls
			dw kw_cls

			; 13: Print "VB self test 4"
			dw kw_printstrvar, str0
			dw kw_printnl

			; 16: Chk LBound(nums), 0
			dw p_chk_c, lit_0, lit_0

			; 17: Chk UBound(nums), 5
			dw p_chk_c, lit_5, lit_5

			; 18: Chk LBound(odd), 1
			dw p_chk_c, lit_1, lit_1

			; 19: Chk UBound(odd), 4
			dw p_chk_c, lit_4, lit_4

			; 20: Chk UBound(grid, 2), 3
			dw p_chk_c, lit_3, lit_3

			; 23: For i = 0 To 5
			dw kw_ztov, var_i
for1_t:

			; 24: nums(i) = 10 - i
			dw kw_sublv, 10, var_i, tmp1
			dw kw_aset, arr_nums, var_i, tmp1

			; 25: Next
			dw kw_next1l_n, var_i, 5, for1_t
for1_e:

			; 26: Chk Total(nums), 45
			dw p_total_c, ad_arr_nums
			dw p_chk_c, var_total_total, lit_45

			; 27: SortUp nums
			dw p_sortup_c, ad_arr_nums

			; 28: Chk nums(0), 5
			dw p_chk_c, arr_nums, lit_5

			; 29: Chk nums(5), 10
			dw p_chk_c, arr_nums+10, lit_10

			; 30: Chk Total(nums), 45
			dw p_total_c, ad_arr_nums
			dw p_chk_c, var_total_total, lit_45

			; 31: For i = 1 To 4
			dw kw_ltov, 1, var_i
for2_t:

			; 32: odd(i) = i * i
			dw kw_mulvv, var_i, var_i, tmp1
			dw kw_aset, arr_odd-2, var_i, tmp1

			; 33: Next
			dw kw_next1l_n, var_i, 4, for2_t
for2_e:

			; 34: Chk Total(odd), 30
			dw p_total_c, ad_arr_odd
			dw p_chk_c, var_total_total, lit_30

			; 35: Chk Lo(odd), 1
			dw p_lo_c, ad_arr_odd
			dw p_chk_c, var_lo_lo, lit_1

			; 36: Chk Hi(odd), 4
			dw p_hi_c, ad_arr_odd
			dw p_chk_c, var_hi_hi, lit_4

			; 37: Chk Count(nums), 6
			dw p_count_c, ad_arr_nums
			dw p_chk_c, var_count_count, lit_6

			; 38: words(0) = "pear"
			dw kw_strcpyn, arr_words, str1, 40

			; 39: words(1) = "apple"
			dw kw_strcpyn, arr_words+41, str2, 40

			; 40: words(2) = "fig"
			dw kw_strcpyn, arr_words+82, str3, 40

			; 41: ChkS Longest(words), "apple"
			dw p_longest_c, ad_arr_words
			dw p_chks_c, var_longest_longest, str2

			; 42: Shout words
			dw p_shout_c, ad_arr_words

			; 43: ChkS words(2), "FIG"
			dw p_chks_c, arr_words+82, str4

			; 44: big(0) = 100000
			dw kw_l_mov, llit_100000, arr_big

			; 45: big(3) = 250000
			dw kw_l_mov, llit_250000, arr_big+12

			; 46: ChkL BigSum(big), 350000
			dw p_bigsum_c, ad_arr_big
			dw p_chkl_c, var_bigsum_bigsum, llit_350000

			; 48: Print
			dw kw_printnl

			; 49: Print "a"; Tab(6); "b"
			dw kw_printstrvar, str5
			dw kw_printtab, lit_6
			dw kw_printstrvar, str6
			dw kw_printnl

			; 50: Print t; " tests, "; bad; " failed"
			dw kw_printint, var_t
			dw kw_printstrvar, str7
			dw kw_printint, var_bad
			dw kw_printstrvar, str8
			dw kw_printnl

			; 51: Print "Press a key";
			dw kw_printstrvar, str9

			; 52: Do : Frame : Loop Until Inkey <> 0
do3_t:
			dw kw_frame
			dw kw_inkey, tmp0
			dw kw_cpnevl, tmp0, 0
			dw kw_goto_iffalse_n, do3_t
do3_e:

			; 53: Print
			dw kw_printnl

			; 54: End
			dw kw_stop

; ============================================================
; sub chk (normal mode)
; ============================================================

p_chk:

			; 57: t = t + 1
			dw kw_inc, var_t

			; 58: Print t; ":";
			dw kw_printint, var_t
			dw kw_printstrvar, str10

			; 59: If got = want Then
			dw kw_cpeqvv, var_chk_got, var_chk_want
			dw kw_goto_iffalse_n, if4_1

			; 60: Print "ok ";
			dw kw_printstrvar, str11

			; 61: Else
			dw if4_e_go
if4_1:

			; 62: Print "FAIL("; got; ") ";
			dw kw_printstrvar, str12
			dw kw_printint, var_chk_got
			dw kw_printstrvar, str13

			; 63: bad = bad + 1
			dw kw_inc, var_bad

			; 64: End If
if4_e:
			dw p_chk_r

