; ============================================================
; Keyword library (rom)
; ============================================================

; Library: ROM - the keyword library is in the ROM NTC CPCFW (NTCFW.ROM).
; Its routines: this jump block, the numbers made into addresses by the ROM at the start.
; Its variables and constants: fixed addresses (RAM #8800 - #A5EF is the ROM's).
ntc_rj_block:
kw_stop:		jp 1
ntc_xn:		jp 2
kw_goto_iffalse_n:	jp 11
kw_forupv_n:	jp 25
kw_next1l_n:	jp 31
kw_next1v_n:	jp 33
kw_ltov:		jp 47
kw_vtov:		jp 48
kw_ztov:		jp 49
kw_inc:		jp 51
kw_dec:		jp 52
kw_add:		jp 53
kw_addl:		jp 54
kw_subvv:	jp 55
kw_sublv:	jp 56
kw_mulvv:	jp 60
kw_scplevv:	jp 81
kw_scpgtvv:	jp 83
kw_scpgevv:	jp 85
kw_cpeqvv:	jp 95
kw_cpnevl:	jp 98
kw_aset:		jp 112
kw_strcpy:	jp 122
kw_strcpyn:	jp 123
kw_strlen:	jp 125
kw_strcmpeq:	jp 126
kw_printstrvar:	jp 129
kw_printint:	jp 131
kw_printnl:	jp 138
kw_printtab:	jp 139
kw_inkey:	jp 144
kw_cls:		jp 147
kw_frame:	jp 152
kw_strucase:	jp 180
kw_pget:		jp 198
kw_pset:		jp 199
kw_psets:	jp 200
kw_lbound:	jp 204
kw_ubound:	jp 205
kw_l_mov:	jp 206
kw_l_add:	jp 209
kw_l_cpeq:	jp 221
kw_l_print:	jp 233
kw_bssinit:	jp 288
NTC_RJ_N	equ 44		; entries
ntc_csp	equ #8800		; ROM data
ntc_nmode	equ #8806		; ROM data
ntc_v_free	equ #8844		; ROM data
ntc_v_romen	equ #884A		; ROM data
ntc_v_romold	equ #884C		; ROM data
ntc_v_stamp	equ #8848		; ROM data
ntc_v_start	equ #8846		; ROM data
			ASSERT ntc_free <= #8800, "Library: ROM - the program and its arrays must end below #8800 (the ROM's RAM)"

; the start: find the ROM in slots 0 - 31, have it patch the jump block. NC = ready;
; C = not there / too old (the message is shown, the caller's ROM selection is back)
ntc_rj_find:
			ld c, 0
			call #B90F		; KL ROM SELECT: B / C = the caller's state and selection
			ld (ntc_rj_old), bc
			ld c, 0
ntc_rj_next:
			push bc
			call #B90F		; KL ROM SELECT: ROM C
			pop bc
			ld a, (#C000)
			cp 1				; a background ROM?
			jr nz, ntc_rj_skip
			ld hl, (#C004)		; its names
			ld a, h
			cp #C0
			jr c, ntc_rj_skip
ntc_rj_name:
			ld a, (hl)
			inc hl
			or a
			jr nz, ntc_rj_name		; to the 0 after the names
			ld de, ntc_rj_sig
			ld b, ntc_rj_sige - ntc_rj_sig
ntc_rj_cmp:
			ld a, (de)
			cp (hl)
			jr nz, ntc_rj_skip
			inc de
			inc hl
			djnz ntc_rj_cmp
			ld e, (hl)
			inc hl
			ld d, (hl)			; its patcher
			ld (ntc_rj_call + 1), de
			ld a, c				; its slot
			ld hl, ntc_rj_block
			ld bc, NTC_RJ_N
ntc_rj_call:
			call 0				; HL = jump block, BC = entries, A = slot; C: DE = a number it hasn't got
			jr c, ntc_rj_lacks
			ld hl, ntc_free
			ld (ntc_v_free), hl
			ld hl, ntc_start
			ld (ntc_v_start), hl
			ld hl, 0
			ld (ntc_v_stamp), hl
			ld a, 0
			ld (ntc_v_romen), a
			ld a, (ntc_rj_old)
			ld (ntc_v_romold), a
			or a				; NC: ready
			ret
ntc_rj_skip:
			inc c
			ld a, c
			cp 32
			jr c, ntc_rj_next
			ld hl, ntc_rj_tnf
			jr ntc_rj_fail
ntc_rj_lacks:
			ld (ntc_rj_num), de
			ld hl, ntc_rj_tlk
ntc_rj_fail:
			push hl
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT: the caller's selection again
			pop hl
			call ntc_rj_puts
			ld hl, ntc_rj_tlk
			or a
			sbc hl, de			; (DE: past the message shown)
			jr nz, ntc_rj_nl
			ld a, (ntc_rj_num + 1)
			call ntc_rj_hex
			ld a, (ntc_rj_num)
			call ntc_rj_hex
ntc_rj_nl:
			ld hl, ntc_rj_tnl
			call ntc_rj_puts
			ei
			call #BB06		; KM WAIT CHAR: a key first (a RUN" program's return resets the machine)
			di
			scf
			ret
ntc_rj_puts:				; HL = text, 0 ends; DE = its start
			ld d, h
			ld e, l
ntc_rj_pl:
			ld a, (hl)
			or a
			ret z
			call #BB5A		; TXT OUTPUT
			inc hl
			jr ntc_rj_pl
ntc_rj_hex:
			push af
			rrca
			rrca
			rrca
			rrca
			call ntc_rj_dig
			pop af
ntc_rj_dig:
			and 15
			add a, #90
			daa
			adc a, #40
			daa
			jp #BB5A
; End: the caller's ROM selection again, then back to the caller
ntc_rj_exit:
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT
			ret
ntc_rj_old:		dw 0			; the caller's ROM selection (C) and state (B)
ntc_rj_num:		dw 0
ntc_rj_sig:		db "NTC", 1, "CPCFW", 0	; the ROM's NTC block
ntc_rj_sige:
ntc_rj_tnf:		db "ROM NTC CPCFW (NTCFW.ROM) not found", 0
ntc_rj_tlk:		db "ROM NTC CPCFW too old: no routine #", 0
ntc_rj_tnl:		db 13, 10, "Press a key", 13, 10, 0

ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bss		equ ntc_end
arr_nums		equ ntc_bss + 0		; 12 bytes
arr_odd		equ ntc_bss + 12		; 8 bytes
arr_words		equ ntc_bss + 20		; 123 bytes
arr_big		equ ntc_bss + 143		; 16 bytes
arr_grid		equ ntc_bss + 159		; 24 bytes
pa_total_a		equ ntc_bss + 183		; 12 bytes
pa_sortup_a		equ ntc_bss + 195		; 12 bytes
pa_lo_a		equ ntc_bss + 207		; 12 bytes
pa_hi_a		equ ntc_bss + 219		; 12 bytes
pa_count_a		equ ntc_bss + 231		; 12 bytes
pa_longest_s		equ ntc_bss + 243		; 12 bytes
pa_shout_s		equ ntc_bss + 255		; 12 bytes
pa_bigsum_v		equ ntc_bss + 267		; 12 bytes
ntc_bss_size	equ 279
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
			SAVEAMSDOS "VBTEST4.BIN", ntc_start, ntc_end - ntc_start, ntc_start
